struct Unit{virtual~Unit()=default;Unit*owner=nullptr;bool aura=true,unitCasting=false;uint32 entry=0;Guid guid{1};Position pos;Motion motion;std::string name="Native target";virtual Creature*ToCreature(){return nullptr;}virtual Player*ToPlayer(){return nullptr;}Unit*ToUnit(){return this;}Unit*GetAnyOwner(){return owner;}bool HasAura(uint32){return aura;}bool HasUnitState(uint32){return unitCasting;}Guid GetGUID(){return guid;}uint32 GetEntry(){return entry;}float GetPositionX(){return pos.x;}float GetPositionY(){return pos.y;}float GetPositionZ(){return pos.z;}float GetOrientation(){return pos.o;}Position GetPosition(){return pos;}std::string const&GetName(){return name;}void SetName(std::string const&n){name=n;}void SetFlag(uint32,uint32){}void RemoveFlag(uint32,uint32){}void SetReactState(uint32){}void SetVisible(bool){}void SetOrientation(float o){pos.o=o;}void setFaction(uint32){}uint32 getFaction(){return 42;}Motion*GetMotionMaster(){return &motion;}Endpoint*GetAI(){return endpoint.exists?&endpoint:nullptr;}Endpoint*AI(){return GetAI();}void AddAura(uint32,Unit*){++actions;}void RemoveAurasDueToSpell(uint32){++removals;}template<class...T>void CastSpell(Unit*target,uint32 spell,T...){casts.push_back({this,target,spell,0});}void CastSpellDelay(Position,uint32 spell,bool,uint32 delay){casts.push_back({this,nullptr,spell,delay});}void CastSpellDelay(Unit*target,uint32 spell,bool,uint32 delay){casts.push_back({this,target,spell,delay});}void SendMeleeAttackStart(Unit*){++actions;}void CombatStart(Unit*){++actions;}};
struct Player:Unit{Player*ToPlayer()override{return this;}void RemoveAura(uint32){++removals;}void CLOSE_GOSSIP_MENU(){++gossipClosed;}};
struct Creature:Unit{Creature*ToCreature()override{return this;}Creature*SummonCreature(uint32,Position);Creature*SummonCreature(uint32,float,float,float,float);Creature*SummonCreature(uint32,float,float,float,float,uint32,uint32);};using TempSummon=Creature;
static std::array<Creature,64>pool;static std::set<uint32>failSpawns;
static Creature*Summon(uint32 entry,Position pos){auto i=spawns++;Require(i<pool.size(),"Fixture spawn pool exhausted");if(failSpawns.count(i))return nullptr;auto&creature=pool[i];creature.entry=entry;creature.pos=pos;creature.guid={i+10};return &creature;}
Creature*Creature::SummonCreature(uint32 e,Position p){return Summon(e,p);}Creature*Creature::SummonCreature(uint32 e,float x,float y,float z,float o){return Summon(e,{x,y,z,o});}Creature*Creature::SummonCreature(uint32 e,float x,float y,float z,float o,uint32,uint32){return Summon(e,{x,y,z,o});}
