struct Base{Creature*me;Instance*instance=nullptr;Unit*caster=nullptr;Unit*owner=nullptr;Position*dest=nullptr;AuraEffect*trigger=nullptr;bool victim=true,casting=false;Scheduler Events;Guid lastPortalGUID;GuidList portalTriggers,animated_staffs,animated_axes,swordLauncherGuids;std::vector<Guid>addsAtBase;
 Base(Creature*c):me(c){}virtual~Base()=default;virtual void UpdateAI(uint32){}virtual bool OnGossipSelect(Player*,GameObject*,uint32,uint32){return false;}Unit*GetCaster(){return caster;}Unit*GetUnitOwner(){return owner;}AuraEffect const*GetTriggeredAuraEff(){return trigger;}Position*GetHitDest(){return dest;}bool UpdateVictim(){return victim;}bool HasUnitState(uint32){return casting;}Creature*FindFriendlyCreature(){return friends.empty()?nullptr:friends.front();}std::list<Creature*>DoFindFriendlyMissingBuff(float,uint32){return friends;}void DoCast(Unit*target,uint32 spell){casts.push_back({me,target,spell,0});}void DoCastVictim(uint32 spell){DoCast(caster,spell);}void DoMeleeAttackIfReady(){++melees;}void SelectTargetList(std::list<Unit*>&out,uint32,uint32,uint32,bool){out=cloneTargets;}Unit*SelectTarget(uint32,uint32,float,bool){return caster;}};
