static void Reset(){randomPicks=paths=randomMoves=homes=actions=talks=melees=spawns=removals=gossipClosed=0;casts.clear();lookups.clear();ships.clear();friends.clear();cloneTargets.clear();failSpawns.clear();endpoint.exists=true;invalidateCaster=nullptr;}
static void Ravager(){Creature actor,owner;Player target;Third0 frame(&actor);frame.caster=&actor;actor.owner=&owner;AuraEffect effect;frame.trigger=&effect;std::list<WorldObject*>targets;frame.FilterTargets(targets);Require(!randomPicks&&casts.empty(),"Empty first-tick list cannot select or cast");targets.push_back(&target);frame.FilterTargets(targets);Require(randomPicks==1&&casts.size()==1&&casts[0].actor==&owner&&casts[0].target==&target&&casts[0].spell==12294,"Original owner-owned first-tick Mortal Strike preserved");effect.tick=2;frame.FilterTargets(targets);Require(randomPicks==1&&casts.size()==1,"Later ticks retain original no-bonus admission");effect.tick=1;frame.trigger=nullptr;frame.FilterTargets(targets);Require(randomPicks==1,"Missing trigger cannot cast bonus");frame.trigger=&effect;owner.aura=false;frame.FilterTargets(targets);Require(randomPicks==1,"Missing set bonus cannot cast");owner.aura=true;actor.owner=nullptr;frame.FilterTargets(targets);Require(casts.size()==2&&casts.back().actor==&actor,"Unowned ravager retains native caster fallback");frame.caster=nullptr;frame.FilterTargets(targets);Require(casts.size()==2,"Missing caster retains original skip");}
static void Withering(){Creature actor,a,b;Position destination;Third1 frame(&actor);frame.caster=&actor;frame.dest=&destination;frame.HandleScript(0);Require(casts.size()==16,"No visual ships must retain all16 real missiles");for(auto const&cast:casts)Require(cast.actor==&actor&&cast.spell==SPELL_WITHERING_FIRE_MISSILE,"Missing ships cannot invent visuals");casts.clear();ships={&a,&b};frame.HandleScript(0);Require(casts.size()==32,"Two real ships retain16missiles and16visuals");uint32 damage=0,visual=0;for(auto const&cast:casts){if(cast.spell==SPELL_WITHERING_FIRE_MISSILE){++damage;Require(cast.actor==&actor&&cast.delay<3000,"Original missile source/delay");}else{++visual;Require((cast.actor==&a||cast.actor==&b)&&cast.spell==SPELL_WITHERING_FIRE_VISUAL&&cast.delay>=3000,"Original visual source/delay");}}Require(damage==16&&visual==16,"Original paired missile/visual counts");casts.clear();ships={&a};frame.HandleScript(0);Require(casts.size()==32,"One real ship retains original shared visual source behavior");casts.clear();frame.dest=nullptr;frame.HandleScript(0);Require(casts.empty(),"Missing destination retains original admission");}
static void Arnath(){Creature actor,friendly;Third2 frame(&actor);frame.Events.pending=EVENT_ARNATH_PW_SHIELD;frame.UpdateAI(1);Require(casts.empty()&&!randomPicks&&frame.Events.scheduled.size()==1&&frame.Events.scheduled[0].first==EVENT_ARNATH_PW_SHIELD,"All-buffed friendly list keeps shield retry without invalid selection");friends={&friendly};frame.Events.pending=EVENT_ARNATH_PW_SHIELD;frame.UpdateAI(1);Require(casts.size()==1&&casts[0].target==&friendly&&casts[0].spell==SPELL_POWER_WORD_SHIELD&&frame.Events.scheduled.size()==2,"Real missing-buff target and native15..20s schedule retained");frame.Events.pending=EVENT_ARNATH_FLASH_HEAL;frame.UpdateAI(1);Require(casts.back().target==&friendly&&casts.back().spell==SPELL_FLASH_HEAL,"Independent friendly heal remains");auto count=casts.size();actor.unitCasting=true;frame.Events.pending=EVENT_ARNATH_PW_SHIELD;frame.UpdateAI(1);Require(casts.size()==count,"Casting admission retained");}
static void Portals(){Creature actor,portal;Instance instance;instance.creature=&portal;Third3 frame(&actor);frame.instance=&instance;frame.PowerSparksHandling();Require(lookups.empty()&&casts.empty()&&!frame.lastPortalGUID,"No loaded portals preserve checkpoint and wait");frame.portalTriggers={{10},{11}};portal.guid={10};frame.PowerSparksHandling();Require(casts.size()==1&&frame.lastPortalGUID.value==10&&lookups.back().value==10,"First available portal opens at original first checkpoint");instance.creature=nullptr;casts.clear();frame.PowerSparksHandling();Require(casts.empty()&&frame.lastPortalGUID.value==10,"Missing next actor cannot consume checkpoint");instance.creature=&portal;portal.guid={11};frame.PowerSparksHandling();Require(frame.lastPortalGUID.value==11&&casts.size()==1,"Later availability opens the actual next portal");portal.guid={10};frame.PowerSparksHandling();Require(frame.lastPortalGUID.value==10&&casts.size()==2,"Original round-robin wrap retained");}
static void Staffs(){Creature actor,staff;Instance instance;instance.creature=&staff;Third4 frame(&actor);frame.instance=&instance;frame.SetData_xin_the_weaponmaster(TYPE_ACTIVATE_ANIMATED_STAFF,1);Require(!randomPicks&&!actions&&lookups.empty(),"No staff actors means no invalid random selection");frame.animated_staffs={{10}};frame.SetData_xin_the_weaponmaster(TYPE_ACTIVATE_ANIMATED_STAFF,1);Require(randomPicks==1&&actions==1&&lookups.back().value==10,"Existing staff activation preserved");instance.creature=nullptr;frame.SetData_xin_the_weaponmaster(TYPE_ACTIVATE_ANIMATED_STAFF,1);Require(actions==1,"Unloaded selected actor cannot execute action");instance.creature=&staff;frame.animated_axes={{12}};frame.SetData_xin_the_weaponmaster(TYPE_ACTIVATE_ANIMATED_AXE,1);Require(actions==3&&randomMoves==1,"Independent axe auras/movement retained");frame.SetData_xin_the_weaponmaster(TYPE_ACTIVATE_ANIMATED_AXE,0);Require(removals==2&&homes==1,"Independent axe cleanup retained");}
static void Pyramid(){Creature actor;Instance instance;Third5 frame(&actor);frame.instance=&instance;failSpawns={0};frame.SpawnPyramidWave(1);Require(spawns==2&&randomMoves==1&&frame.addsAtBase.size()==1&&frame.addsAtBase[0].value==11,"Failed individual pyramid summon cannot enter movement/tracking and later adds continue");frame.SpawnPyramidWave(99);Require(spawns==2,"Unmatched wave retains no-spawn behavior");Reset();Third5 fresh(&actor);fresh.instance=&instance;fresh.SpawnPyramidWave(1);Require(spawns==2&&randomMoves==2&&fresh.addsAtBase.size()==2,"Successful authored wave retains all movement/tracking");}
static void Wind(){Creature actor;Player player;GameObject stone;Third6 frame(&actor);stone.entry=180529;failSpawns={0};frame.OnGossipSelect(&player,&stone,0,0);Require(spawns==1&&!removals&&casts.empty()&&!actions&&gossipClosed==1,"Failed selected summon retains offering and closes gossip without combat effects");for(uint32 entry:{180529u,180534u,180466u}){Reset();stone.entry=entry;frame.OnGossipSelect(&player,&stone,0,0);Require(spawns==1&&removals==1&&actions==2&&talks==1&&gossipClosed==1&&casts.size()==1&&casts[0].actor==&pool[0]&&casts[0].target==&pool[0]&&casts[0].spell==25035,"All3stone tiers retain exactly-one offering consumption and actual summoned enemy combat/visual");Reset();failSpawns={0};frame.OnGossipSelect(&player,&stone,0,0);Require(!removals&&casts.empty()&&!actions,"Each tier retains offering on failed spawn");}Reset();stone.entry=0;frame.OnGossipSelect(&player,&stone,0,0);Require(!spawns&&!removals&&gossipClosed==1,"Unknown stone cannot consume offering");}
static void Elerethe(){Creature actor;Third7 frame(&actor);failSpawns={2};frame.Intro();Require(spawns==10&&!paths,"Missing first bridge shadow cannot start route while all other intro spawns continue");Reset();frame.Intro();Require(spawns==10&&paths==1&&casts.size()==1&&casts[0].spell==SPELL_DRUID_TRANSFORM&&casts[0].delay==1000,"Successful intro preserves7shadowspawns,one original route anddelayed transform");Reset();for(uint32 i=0;i<10;++i)failSpawns.insert(i);frame.Intro();Require(spawns==10&&!paths,"Every independent failed intro spawn handled without a false route");}
static void Clones(){Creature actor;Player first,second;cloneTargets={&first,&second};Third8 frame(&actor);failSpawns={0};frame.SummonClones();Require(spawns==2&&casts.size()==2&&actions==1&&casts[0].actor==&second&&casts[0].target==&pool[1]&&casts[0].spell==SPELL_CLONE_NAME&&casts[1].spell==SPELL_CLONE_MODEL&&pool[1].name==second.name,"Failed clone skips only that player;later clone retains name/model/faction/attack");Reset();cloneTargets={&first,&second};frame.SummonClones();Require(spawns==2&&casts.size()==4&&actions==2,"All successful clones retain independent model/name/attack");Reset();frame.SummonClones();Require(!spawns,"Empty actual target list creates no clones");}
static void Shatter(){Creature crystal,actor;Third9 frame(&actor);frame.owner=&crystal;crystal.entry=NPC_CRYSTAL_TARGETED;frame.OnTick(nullptr);Require(actions==1&&casts.empty(),"Missing clicker must retain independent crystal disable/cleanup without a lost-caster cast");for(auto pair:{std::pair<uint32,uint32>{NPC_CRYSTAL_TARGETED,SPELL_TARGETED},{NPC_CRYSTAL_BURNING,SPELL_BURNING_EMBERS},{NPC_CRYSTAL_FOUL_STEPS,SPELL_FOUL_STEPS},{NPC_CRYSTAL_ARCANE_SINGULARITY,SPELL_ARCANE_SINGULARITY}}){casts.clear();frame.caster=&actor;crystal.entry=pair.first;frame.OnTick(nullptr);Require(casts.size()==1&&casts[0].actor==&actor&&casts[0].target==&actor&&casts[0].spell==pair.second,"All4crystal types retain original clicker self-cast debuff");}casts.clear();frame.caster=&actor;invalidateCaster=&frame;frame.OnTick(nullptr);Require(casts.empty(),"Independent crystal AI action may invalidate caster before later effect");invalidateCaster=nullptr;frame.caster=&actor;endpoint.exists=false;frame.OnTick(nullptr);Require(casts.size()==1,"Unavailable current crystal AI skips optional action without invalid AI dereference");}
int main(int argc,char**argv){try{Require(argc==2,"Case required");Reset();uint32 which=uint32(std::stoul(argv[1]));switch(which){case 0:Ravager();break;case 1:Withering();break;case 2:Arnath();break;case 3:Portals();break;case 4:Staffs();break;case 5:Pyramid();break;case 6:Wind();break;case 7:Elerethe();break;case 8:Clones();break;case 9:Shatter();break;default:throw std::runtime_error("Unknown case");}std::cout<<"PASS complete production third-batch case "<<which<<":empty/missing endpoints and valid behavior;controlledspatial/summon/clock/cast endpoints,client traversal separate\n";return 0;}catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
